import {getRequestConfig} from "next-intl/server";

export default getRequestConfig(async ({locale}) => {
	const loc = locale || "es";
	try {
		const messages = (await import(`./src/messages/${loc}.json`)).default;
		return {locale: loc, messages};
	} catch (e) {
		// Fallback: load Spanish as default if locale file missing
		const messages = (await import("./src/messages/es.json")).default;
		return {locale: "es", messages};
	}
});

// Export users to dev-output/users-<timestamp>.json
import { createClient } from '@supabase/supabase-js';
import fs from 'fs';
import path from 'path';

const url = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const service = process.env.SUPABASE_SERVICE_ROLE || '';

async function main() {
  if (!url || !service) {
    console.error('Missing NEXT_PUBLIC_SUPABASE_URL or SUPABASE_SERVICE_ROLE');
    process.exit(1);
  }
  const supabase = createClient(url, service);

  // Try admin API to list users (auth schema)
  let users: any[] = [];
  try {
    let page = 1;
    const perPage = 1000;
    // @ts-ignore - admin listUsers exists in supabase-js v2
    while (true) {
      // @ts-ignore
      const { data, error } = await supabase.auth.admin.listUsers({ page, perPage });
      if (error) throw error;
      if (!data?.users?.length) break;
      users.push(...data.users);
      if (data.users.length < perPage) break;
      page++;
    }
  } catch (e) {
    console.warn('Falling back to user_profiles only:', (e as any)?.message);
  }

  // Join with profiles if possible
  const { data: profiles } = await supabase
    .from('user_profiles')
    .select('user_id,email,plan,role,metadata,created_at,updated_at');
  const profilesMap = new Map((profiles || []).map((p: any) => [p.user_id, p]));

  const out = users.length
    ? users.map(u => ({
        id: u.id,
        email: u.email,
        created_at: u.created_at,
        last_sign_in_at: u.last_sign_in_at,
        phone: u.phone,
        app_metadata: u.app_metadata,
        user_metadata: u.user_metadata,
        profile: profilesMap.get(u.id) || null,
      }))
    : (profiles || []);

  const dir = path.join(process.cwd(), 'dev-output');
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, `users-${new Date().toISOString().replace(/[:.]/g,'-')}.json`);
  fs.writeFileSync(file, JSON.stringify(out, null, 2), 'utf8');
  console.log('Exported', out.length, 'records to', file);
}

main().catch(err => { console.error(err); process.exit(1); });

const fs = require('fs');
const path = '.env.local';
const out = '.env.local.fixed';

if (!fs.existsSync(path)) {
  console.error('No .env.local file found');
  process.exit(1);
}

const raw = fs.readFileSync(path, 'utf8');
// Normalize newlines and split
const lines = raw.split(/\r?\n/);
const outLines = [];
let lastKeyLineIndex = -1;

const keyPattern = /([A-Za-z_][A-Za-z0-9_]*)=/g;

for (const originalLine of lines) {
  const line = originalLine.trimEnd();

  // Leave blank lines and comments untouched
  if (line.length === 0 || line.startsWith('#')) {
    outLines.push(line);
    lastKeyLineIndex = outLines.length - 1;
    continue;
  }

  // If the line looks like it contains multiple key=value pairs glued together,
  // split by occurrences of KEY= (where KEY is an identifier) and keep each chunk
  // as its own line.
  const matches = [];
  while (true) {
    const m = keyPattern.exec(line);
    if (!m) break;
    matches.push({ key: m[1], idx: m.index });
  }

  if (matches.length > 1) {
    // Split into multiple segments from each match start
    for (let i = 0; i < matches.length; i++) {
      const start = matches[i].idx;
      const end = i + 1 < matches.length ? matches[i + 1].idx : line.length;
      let seg = line.slice(start, end).trim();
      // If there is an inline comment (space + #) split it into own line
      const commentIndex = seg.indexOf(' #');
      if (commentIndex !== -1) {
        const left = seg.slice(0, commentIndex).trim();
        const right = seg.slice(commentIndex + 1).trim(); // keep '#'
        if (left.length) outLines.push(left);
        if (right.length) outLines.push('#' + right.replace(/^#+/, '')); // ensure starting '#'
      } else {
        if (seg.length) outLines.push(seg);
      }
    }
    lastKeyLineIndex = outLines.length - 1;
    continue;
  }

  // If the line includes at least one '=' it's either a key=value or a broken continuation
  if (line.includes('=')) {
    // If there's an inline comment in the single line (like "KEY=value   # comment"), split it
    const commentIndex = line.indexOf(' #');
    if (commentIndex !== -1) {
      const left = line.slice(0, commentIndex).trim();
      const right = line.slice(commentIndex + 1).trim();
      if (left.length) outLines.push(left);
      if (right.length) outLines.push('#' + right.replace(/^#+/, ''));
    } else {
      outLines.push(line);
    }
    lastKeyLineIndex = outLines.length - 1;
  } else {
    // Continuation of previous value: append without inserting spurious spaces
    if (lastKeyLineIndex >= 0) {
      outLines[lastKeyLineIndex] = outLines[lastKeyLineIndex] + line.trim();
    } else {
      // nothing to append to ÔÇö keep the line
      outLines.push(line);
      lastKeyLineIndex = outLines.length - 1;
    }
  }
}

fs.writeFileSync(out, outLines.join('\n'));
console.log('Wrote', out);

