export default async function VersionsPage() {
  const supabase = await createServerComponentClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) redirect("/?auth=required");

  const { data: versions } = await supabase
    .from("recipe_versions")
    .select("id, base_recipe_id, variant_type, created_at, content")
    .eq("user_id", user.id)
    .order("created_at", { ascending: false });

  const baseIds = Array.from(new Set((versions || []).map((v: any) => v.base_recipe_id)));
  let baseRecipes: Record<number, any> = {};
  if (baseIds.length) {
    const { data } = await supabase
      .from("recipes")
      .select("id,title,slug,user_id")
      .in("id", baseIds);
    for (const r of data || []) baseRecipes[r.id] = r;
  }

  return (
    <main className="max-w-3xl mx-auto p-6">
      <h1 className="text-2xl font-bold text-amber-800">­ƒÆ¥ <IntlText k="versions.title" fallback="Mis versiones IA" /></h1>
      {!versions || versions.length === 0 ? (
        <p className="text-neutral-500 mt-3"><IntlText k="versions.empty" fallback="A├║n no has guardado versiones." /></p>
      ) : (
        <ul className="mt-4 space-y-3">
          {versions.map((v: any) => {
            const base = baseRecipes[v.base_recipe_id];
            return (
              <li key={v.id} className="border rounded p-3">
                <div className="text-sm text-neutral-500">
                  {new Date(v.created_at).toLocaleString()} ÔÇó <IntlText k="versions.type" fallback="Tipo" />: {v.variant_type}
                </div>
                <div className="mt-1">
                  {base ? (
                    <Link href={`/r/${base.user_id}/${base.slug}`} className="font-medium text-amber-800">
                      {base.title}
                    </Link>
                  ) : (
                    <span className="font-medium"><IntlText k="versions.baseDeleted" fallback="Receta base eliminada" /></span>
                  )}
                </div>
                {v.content?.text && (
                  <pre className="mt-2 whitespace-pre-wrap text-xs bg-amber-50 p-2 rounded border">
                    {v.content.text}
                  </pre>
                )}
              </li>
            );
          })}
        </ul>
      )}
    </main>
  );
}

"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import LegacyPageWrapper from "@/components/layout/LegacyPageWrapper";

export default function InvitePage({ params }: { params: { token: string } }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [done, setDone] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  async function handleAccept() {
    if (!email || !password) {
      setError("Email y contrase├▒a son requeridos");
      return;
    }

    setLoading(true);
    setError("");

    try {
      const res = await fetch("/api/invite/accept", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token: params.token, email, password }),
      });

      const data = await res.json();

      if (res.ok) {
        setDone(true);
        setTimeout(() => router.push("/login"), 2000);
      } else {
        setError(data.error || "Error al aceptar la invitaci├│n.");
      }
    } catch (err) {
      setError("Error de conexi├│n. Intenta de nuevo.");
    } finally {
      setLoading(false);
    }
  }

  if (done) {
    return (
      <LegacyPageWrapper>
        <div className="min-h-screen flex items-center justify-center text-center bg-gradient-to-br from-orange-50 to-yellow-50">
          <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md">
            <h1 className="text-2xl font-semibold mb-3 text-orange-600">­ƒÄë Invitaci├│n confirmada</h1>
            <p className="text-neutral-600">
              Tu cuenta ha sido creada. Redirigiendo al login...
            </p>
          </div>
        </div>
      </LegacyPageWrapper>
    );
  }

  return (
    <LegacyPageWrapper>
      <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-gradient-to-br from-orange-50 to-yellow-50">
        <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full">
          <div className="text-center mb-6">
            <h1 className="text-3xl font-bold text-orange-600 mb-2">­ƒÉô Cocorico</h1>
            <h2 className="text-xl font-semibold text-neutral-800">Invitaci├│n privada</h2>
          </div>

          <p className="text-neutral-600 mb-6 text-center">
            Has sido invitado a participar en la <strong>beta cerrada</strong> de Cocorico.
            Completa tus datos para unirte.
          </p>

          <div className="space-y-4">
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
                Email
              </label>
              <input
                id="email"
                type="email"
                placeholder="tu@email.com"
                className="border border-gray-300 p-3 rounded-lg w-full focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                disabled={loading}
              />
            </div>

            <div>
              <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-1">
                Contrase├▒a
              </label>
              <input
                id="password"
                type="password"
                placeholder="M├¡nimo 6 caracteres"
                className="border border-gray-300 p-3 rounded-lg w-full focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                disabled={loading}
              />
            </div>

            <button
              onClick={handleAccept}
              disabled={loading}
              className="w-full bg-orange-600 hover:bg-orange-700 text-white px-6 py-3 rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? "Creando cuenta..." : "Aceptar invitaci├│n"}
            </button>
          </div>

          {error && (
            <div className="mt-4 bg-red-50 text-red-600 px-4 py-3 rounded-lg text-sm">
              {error}
            </div>
          )}

          <p className="mt-6 text-center text-sm text-gray-500">
            ┬┐Ya tienes cuenta?{" "}
            <a href="/login" className="text-orange-600 hover:underline">
              Inicia sesi├│n
            </a>
          </p>
        </div>
      </div>
    </LegacyPageWrapper>
  );
}

