import CocoricoMascot, { useMascotMood } from "@/components/CocoricoMascot";

type Msg = Pick<ChatMessage, 'role' | 'content'>;

export default function ChatBox() {
  const [messages, setMessages] = useState<Msg[]>([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorCode, setErrorCode] = useState<number | null>(null);
  const { mood, setMood } = useMascotMood("default");

  async function sendMessage(e: React.FormEvent) {
    e.preventDefault();
    const validation = validateMessage(input);
    if (!validation.isValid) {
      alert(validation.error);
      return;
    }

    const userMsg: Msg = { role: "user", content: validation.value! };
    setMessages((m) => [...m, userMsg]);
    setInput("");
    setLoading(true);
    setMood("thinking");

    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: validation.value }),
      });

      if (res.status === 429) {
        setErrorCode(429);
      }
      const json = await res.json() as ChatResponse;
      const assistantMsg: Msg = {
        role: "assistant",
        content: json.answer || "Hubo un error. Int├®ntalo otra vez.",
      };
      setMessages((m) => [...m, assistantMsg]);
      setMood("happy", 3000);
    } catch {
      setMessages((m) => [
        ...m,
        { role: "assistant", content: "Error de red. Revisa tu conexi├│n." },
      ]);
      setMood("alert", 2000);
