        {messages.length === 0 && (
          <p className="text-sm text-neutral-500">
            Escribe tu duda (por ejemplo ÔÇ£┬┐Este producto es ultraprocesado?ÔÇØ o ÔÇ£Ideas para cenar con br├│coliÔÇØ)
          </p>
        )}
        {messages.map((m, i) => (
          <div key={i} className={m.role === "user" ? "text-right" : "text-left"}>
            <div
              className={
                "inline-block px-3 py-2 rounded-lg " +
                (m.role === "user"
                  ? "bg-cocorico-red text-white dark:bg-amber-600"
                  : "bg-neutral-100 text-neutral-900 dark:bg-neutral-800 dark:text-neutral-100")
              }
            >
              {m.content}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex items-center gap-2">
            <div className="animate-pulse text-xs text-neutral-500 dark:text-neutral-400">
              ­ƒÉô Cocorico est├í pensandoÔÇª
            </div>
          </div>
        )}
        {errorCode === 429 && (
          <div className="rounded-lg border p-4 mt-3 bg-yellow-50">
            <p className="mb-3">Has usado tu l├¡mite diario gratuito. P├ísate a <b>Premium</b> para uso ilimitado.</p>
            <SubscribeButton />
          </div>
        )}
      </div>

      <form onSubmit={sendMessage} className="flex gap-2">
        <input
          className="flex-1 border border-neutral-200 dark:border-neutral-700 rounded px-3 py-2 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 text-base"
          placeholder="Escribe tu mensajeÔÇª"
          value={input}
          onChange={(e) => setInput(e.target.value)}
        />
        <button
          type="submit"
          disabled={loading}
          className="px-4 py-2 rounded bg-cocorico-red hover:bg-cocorico-red/90 dark:bg-amber-600 dark:hover:bg-amber-700 text-white disabled:opacity-50 transition"
        >
          Enviar
        </button>
      </form>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
/* eslint-disable jsx-a11y/aria-proptypes */
import { usePathname, useRouter } from "next/navigation";

// Idiomas soportados y futuros. 'available' indica si existe archivo de traducci├│n.
// BLOQUE 5: English marcado como available:false hasta completar traducciones
const SUPPORTED = [
  { code: "es", name: "Espa├▒ol", flag: "­ƒç¬­ƒç©", available: true, aliases: ["espa├▒ol", "spanish", "castellano", "es"] },
  { code: "en", name: "English", flag: "­ƒç¼­ƒçº", available: true, aliases: ["english", "ingl├®s", "en"] },
  { code: "fr", name: "Fran├ºais", flag: "­ƒç½­ƒçÀ", available: true, aliases: ["frances", "french", "franc├®s", "fr"] },
  { code: "de", name: "Deutsch", flag: "­ƒç®­ƒç¬", available: true, aliases: ["aleman", "german", "alem├ín", "de"] },
  { code: "it", name: "Italiano", flag: "­ƒç«­ƒç╣", available: true, aliases: ["italiano", "italian", "it"] },
  { code: "pt", name: "Portugu├¬s", flag: "­ƒçÁ­ƒç╣", available: true, aliases: ["portugues", "portuguese", "portugu├¬s", "pt"] },
  { code: "ja", name: "µùÑµ£¼Þ¬×", flag: "­ƒç»­ƒçÁ", available: true, aliases: ["japanese", "japones", "japon├®s", "ja"] },
  { code: "ko", name: "Ýò£ÛÁ¡ýû┤", flag: "­ƒç░­ƒçÀ", available: true, aliases: ["korean", "coreano", "ko"] },
  { code: "zh", name: "õ©¡µûç", flag: "­ƒç¿­ƒç│", available: true, aliases: ["chinese", "chino", "zh"] },
  { code: "ar", name: "Ïº┘äÏ╣Ï▒Ï¿┘èÏ®", flag: "­ƒç©­ƒçª", available: true, aliases: ["arabic", "arabe", "├írabe", "ar"] },
];

function detectCurrentLocale(pathname: string | null) {
  if (!pathname) return null;
  const first = pathname.split("/").filter(Boolean)[0];
  return first && SUPPORTED.map(l => l.code).includes(first) ? first : null;
}

export default function LanguageSelector({ compact = false }: { compact?: boolean }) {
  const router = useRouter();
  const pathname = usePathname();
  const currentLocale = useMemo(() => detectCurrentLocale(pathname) ?? "es", [pathname]);

  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return SUPPORTED;
    return SUPPORTED.filter((l) =>
      [l.name, l.code, ...(l.aliases || [])]
        .join(" ")
        .toLowerCase()
        .includes(q)
    );
  }, [query]);

  function goToLocale(code: string) {
    const langObj = SUPPORTED.find(l => l.code === code);
    if (!langObj) return;
    if (!langObj.available) {
      // feedback visual cuando idioma no disponible
      const el = document.getElementById(`lang-${code}`);
      if (el) {
        el.classList.add('animate-pulse');
        setTimeout(() => el.classList.remove('animate-pulse'), 600);
      }
      return;
    }
    const parts = (pathname || "/").split("/").filter(Boolean);
    let target = "/" + code;
    if (parts.length > 0 && SUPPORTED.map(l=>l.code).includes(parts[0])) {
      const rest = parts.slice(1).join("/");
      if (rest) target += "/" + rest;
    } else if (pathname && pathname !== "/") {
      target += pathname;
    }
    setOpen(false);
    router.push(target.replace(/\/+$/, ""));
  }

  useEffect(() => {
    function onEsc(e: KeyboardEvent) {
