"use client";
import { useRef, useEffect, useState } from "react";
import * as cocoSsd from "@tensorflow-models/coco-ssd";
import "@tensorflow/tfjs";

type Mode = "local" | "cloud";

export default function LiveVision({ onDetect, mode = "local" }: { onDetect: (labels: string[]) => void; mode?: Mode }) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [model, setModel] = useState<any>(null);
  const [error, setError] = useState<string>("");
  const [permissionState, setPermissionState] = useState<"idle" | "requesting" | "granted" | "denied">("idle");

  async function requestCameraAccess() {
    setPermissionState("requesting");
    setError("");
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: "environment" } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setPermissionState("granted");
      return stream;
    } catch (e: any) {
      setPermissionState("denied");
      if (e.name === "NotAllowedError" || e.name === "PermissionDeniedError") {
        setError("Acceso a la c├ímara denegado. Por favor, permite el acceso en la configuraci├│n de tu navegador.");
      } else if (e.name === "NotFoundError") {
        setError("No se encontr├│ ninguna c├ímara en tu dispositivo.");
      } else {
        setError(e?.message || "No se pudo acceder a la c├ímara");
      }
      throw e;
    }
  }

  useEffect(() => {
    let stream: MediaStream | null = null;
    async function init() {
      try {
        const loaded = await cocoSsd.load();
        setModel(loaded);
        // NO iniciamos la c├ímara autom├íticamente, esperamos click del usuario
      } catch (e: any) {
        setError(e?.message || "No se pudo cargar el modelo de visi├│n");
      }
    }
    init();
    return () => {
      const video = videoRef.current;
      if (video?.srcObject) {
        (video.srcObject as MediaStream).getTracks().forEach((track) => track.stop());
      }
    };
  }, []);

  useEffect(() => {
    if (!model || permissionState !== "granted") return;
    const interval = setInterval(async () => {
      if (!videoRef.current) return;
      try {
        if (mode === "local") {
          const predictions = await model.detect(videoRef.current);
          const labels = predictions.map((p: any) => p.class as string);
          onDetect(Array.from(new Set(labels)));
        } else {
          const v = videoRef.current;
          if (!v.videoWidth || !v.videoHeight) return;
          let canvas = canvasRef.current;
          if (!canvas) {
            canvas = document.createElement("canvas");
          }
          canvas.width = v.videoWidth;
          canvas.height = v.videoHeight;
          const ctx = canvas.getContext("2d");
          if (!ctx) return;
          ctx.drawImage(v, 0, 0, canvas.width, canvas.height);
          const blob: Blob | null = await new Promise((resolve) => canvas.toBlob(resolve as any, "image/jpeg", 0.8));
          if (!blob) return;
          const form = new FormData();
          form.append("image", blob, "frame.jpg");
          const res = await fetch("/api/ai/live-vision", { method: "POST", body: form });
          if (!res.ok) return;
          const data = await res.json();
          const labels: string[] = Array.from(new Set((data.ingredients || []).filter(Boolean)));
          if (labels.length) onDetect(labels);
        }
      } catch {}
    }, 2000);
    return () => clearInterval(interval);
  }, [model, onDetect, mode, permissionState]);

  if (permissionState === "idle" || permissionState === "requesting") {
    return (
      <div className="p-8 border-2 border-dashed border-neutral-300 dark:border-neutral-700 rounded-xl bg-gradient-to-br from-orange-50/40 to-yellow-50/40 dark:from-neutral-800 dark:to-neutral-800 flex flex-col items-center justify-center text-center gap-4 min-h-[320px]">
        <div className="text-6xl">­ƒô©</div>
        <div>
          <h3 className="font-semibold text-lg mb-1">Activar C├ímara en Vivo</h3>
          <p className="text-sm text-neutral-600 dark:text-neutral-400 max-w-md">
            Para detectar ingredientes en tiempo real, necesitamos acceso a tu c├ímara.
            Haz clic en el bot├│n y acepta el permiso cuando tu navegador lo solicite.
          </p>
        </div>
        <button
          onClick={requestCameraAccess}
          disabled={permissionState === "requesting"}
          className="px-6 py-3 bg-gradient-to-r from-orange-500 to-amber-500 text-white rounded-lg font-semibold hover:from-orange-600 hover:to-amber-600 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg"
        >
          {permissionState === "requesting" ? "ÔÅ│ Esperando permiso..." : "­ƒÄÑ Activar C├ímara"}
        </button>
        {error && (
          <div className="mt-2 px-4 py-2 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg text-sm text-red-700 dark:text-red-400">
            {error}
          </div>
        )}
      </div>
    );
  }

  if (permissionState === "denied") {
    return (
      <div className="p-8 border-2 border-red-300 dark:border-red-800 rounded-xl bg-red-50/40 dark:bg-red-900/10 flex flex-col items-center justify-center text-center gap-4 min-h-[320px]">
        <div className="text-6xl">­ƒÜ½</div>
        <div>
          <h3 className="font-semibold text-lg mb-1 text-red-800 dark:text-red-300">Acceso Denegado</h3>
          <p className="text-sm text-red-700 dark:text-red-400 max-w-md">
            {error || "No pudimos acceder a la c├ímara. Verifica los permisos en la configuraci├│n de tu navegador."}
          </p>
        </div>
        <button
          onClick={() => {
            setPermissionState("idle");
            setError("");
          }}
          className="px-4 py-2 bg-white dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-600 rounded-lg text-sm hover:bg-neutral-50 dark:hover:bg-neutral-700 transition"
        >
          ­ƒöä Intentar de Nuevo
        </button>
        <details className="mt-2 max-w-md">
          <summary className="text-xs text-neutral-600 dark:text-neutral-400 cursor-pointer hover:text-neutral-800 dark:hover:text-neutral-200">
            ┬┐C├│mo habilitar la c├ímara?
          </summary>
          <div className="mt-2 text-xs text-left text-neutral-600 dark:text-neutral-400 space-y-1">
            <p><strong>Chrome/Edge:</strong> Click en el icono ­ƒöÆ junto a la URL ÔåÆ Permisos del sitio ÔåÆ C├ímara ÔåÆ Permitir</p>
            <p><strong>Firefox:</strong> Click en ­ƒöÆ ÔåÆ Borrar permisos y recarga ÔåÆ Click en Activar C├ímara</p>
            <p><strong>Safari:</strong> Safari ÔåÆ Preferencias ÔåÆ Sitios web ÔåÆ C├ímara ÔåÆ Permitir para este sitio</p>
          </div>
        </details>
      </div>
    );
  }

  return (
    <div className="p-4 border rounded-xl bg-white dark:bg-neutral-900 shadow-sm">
      <video ref={videoRef} autoPlay muted playsInline width={640} height={360} className="rounded-lg w-full h-auto bg-black" />
      <div className="flex items-center justify-between mt-2">
        <p className="text-sm text-neutral-500">{error || "­ƒƒó Detectando ingredientes en vivo..."}</p>
        <button
          onClick={() => {
            const video = videoRef.current;
            if (video?.srcObject) {
              (video.srcObject as MediaStream).getTracks().forEach(t => t.stop());
              video.srcObject = null;
            }
            setPermissionState("idle");
          }}
          className="text-xs px-2 py-1 rounded bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 dark:hover:bg-neutral-700 transition"
        >
          ÔÅ╣´©Å Detener
        </button>
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { requestPermission } from "@/firebase";
import { savePushToken } from "@/utils/push";
import { Bell, BellOff, X } from "lucide-react";

export default function PushNotificationPrompt() {
  const [show, setShow] = useState(false);
  const [permission, setPermission] = useState<NotificationPermission>("default");

  useEffect(() => {
    if (typeof window === "undefined") return;
    
    // Verificar permiso actual
    const currentPermission = Notification.permission;
    setPermission(currentPermission);

    // Mostrar prompt solo si no se ha decidido y hay usuario logueado
    const hasDecided = localStorage.getItem("push_notification_decided");
    if (currentPermission === "default" && !hasDecided) {
      // Esperar 5 segundos antes de mostrar el prompt
      const timer = setTimeout(() => setShow(true), 5000);
      return () => clearTimeout(timer);
    }
  }, []);

  async function handleAccept() {
    const token = await requestPermission();
    if (token) {
      await savePushToken(token);
      setPermission("granted");
    } else {
      setPermission("denied");
    }
    localStorage.setItem("push_notification_decided", "true");
    setShow(false);
  }

  function handleDismiss() {
    localStorage.setItem("push_notification_decided", "true");
    setShow(false);
  }

  if (!show || permission !== "default") return null;

  return (
    <div className="fixed bottom-4 right-4 z-50 max-w-sm animate-slide-up">
      <div className="bg-white dark:bg-neutral-800 rounded-lg shadow-2xl border-2 border-cocorico-yellow dark:border-amber-500 p-4">
        <div className="flex items-start gap-3">
          <div className="flex-shrink-0 w-10 h-10 rounded-full bg-cocorico-yellow/20 dark:bg-amber-500/20 flex items-center justify-center">
            <Bell className="w-5 h-5 text-cocorico-red dark:text-amber-400" />
          </div>
          
          <div className="flex-1">
            <h3 className="font-semibold text-sm text-neutral-900 dark:text-neutral-100 mb-1">
              ┬┐Activar notificaciones? ­ƒÉô
            </h3>
            <p className="text-xs text-neutral-600 dark:text-neutral-400 mb-3">
              Recibe recordatorios de cocina, nuevos likes y cuando subas de nivel
            </p>
            
            <div className="flex gap-2">
              <button
                onClick={handleAccept}
                className="flex-1 px-3 py-2 bg-cocorico-red dark:bg-amber-500 text-white rounded-md text-xs font-semibold hover:bg-cocorico-orange dark:hover:bg-amber-600 transition"
              >
                Activar
              </button>
              <button
                onClick={handleDismiss}
                className="px-3 py-2 bg-neutral-100 dark:bg-neutral-700 text-neutral-700 dark:text-neutral-300 rounded-md text-xs font-medium hover:bg-neutral-200 dark:hover:bg-neutral-600 transition"
              >
                Ahora no
              </button>
            </div>
          </div>
          
          <button
            onClick={handleDismiss}
            aria-label="Cerrar aviso de notificaciones"
            title="Cerrar"
            className="flex-shrink-0 w-6 h-6 rounded-full hover:bg-neutral-100 dark:hover:bg-neutral-700 flex items-center justify-center transition"
          >
            <X className="w-4 h-4 text-neutral-400" />
          </button>
        </div>
      </div>
    </div>
  );
}

