"use client";

import { useEffect, useState } from "react";
import { createClientComponentClient } from "@/lib/supabase/client";
import GlassCard from "@/components/ui/GlassCard";
import { Flame, Trophy, Star, TrendingUp } from "lucide-react";

interface UserStats {
  level: number;
  xp: number;
  xpToNextLevel: number;
  streak: number;
  totalRecipes: number;
  weekActivity: number;
}

export default function ProgressWidget() {
  const [stats, setStats] = useState<UserStats | null>(null);
  const [loading, setLoading] = useState(true);
  const supabase = createClientComponentClient();

  useEffect(() => {
    async function loadStats() {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) {
          setLoading(false);
          return;
        }

        // Get user profile
        const { data: profile } = await supabase
          .from("profiles")
          .select("level, xp, streak")
          .eq("id", user.id)
          .single();

        // Get recipe count
        const { count: recipeCount } = await supabase
          .from("recipes")
          .select("*", { count: "exact", head: true })
          .eq("user_id", user.id);

        // Calculate week activity (interactions in last 7 days)
        const sevenDaysAgo = new Date();
        sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
        
        const { count: weekCount } = await supabase
          .from("user_interactions")
          .select("*", { count: "exact", head: true })
          .eq("user_id", user.id)
          .gte("created_at", sevenDaysAgo.toISOString());

        const level = profile?.level || 1;
        const xp = profile?.xp || 0;
        const xpToNextLevel = level * 100; // Simple formula

        setStats({
          level,
          xp,
          xpToNextLevel,
          streak: profile?.streak || 0,
          totalRecipes: recipeCount || 0,
          weekActivity: weekCount || 0,
        });
      } catch (error) {
        console.error("Error loading stats:", error);
      } finally {
        setLoading(false);
      }
    }

    loadStats();
  }, [supabase]);

  if (loading) {
    return (
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {[1, 2, 3, 4].map((i) => (
          <GlassCard key={i} className="h-24 animate-pulse bg-neutral-200/50 dark:bg-neutral-800/50" />
        ))}
      </div>
    );
  }

  if (!stats) return null;

  const xpProgress = (stats.xp / stats.xpToNextLevel) * 100;

  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
      {/* Level Widget */}
      <GlassCard className="p-4 hover:scale-[1.02] transition-transform">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-cocorico-mango to-cocorico-datil flex items-center justify-center text-white font-bold text-lg shadow-lg">
            {stats.level}
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-xs text-neutral-600 dark:text-neutral-400 font-semibold">Nivel</p>
            <div className="flex items-center gap-2">
              <div className="flex-1 h-2 bg-neutral-200 dark:bg-neutral-700 rounded-full overflow-hidden">
                <div
                  className="h-full bg-gradient-to-r from-cocorico-mango to-cocorico-datil transition-all duration-500"
                  style={{ width: `${xpProgress}%` }}
                />
              </div>
            </div>
            <p className="text-xs text-neutral-500 dark:text-neutral-500 mt-1">
              {stats.xp}/{stats.xpToNextLevel} XP
            </p>
          </div>
        </div>
      </GlassCard>

      {/* Streak Widget */}
      <GlassCard className="p-4 hover:scale-[1.02] transition-transform">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-cocorico-red to-cocorico-mango flex items-center justify-center shadow-lg">
            <Flame className="w-6 h-6 text-white" />
          </div>
          <div>
            <p className="text-2xl font-bold text-cocorico-red dark:text-amber-400">
              {stats.streak}
            </p>
            <p className="text-xs text-neutral-600 dark:text-neutral-400 font-semibold">
              D├¡as de racha
            </p>
          </div>
        </div>
      </GlassCard>

      {/* Recipes Widget */}
      <GlassCard className="p-4 hover:scale-[1.02] transition-transform">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-cocorico-avocado to-cocorico-turquoise flex items-center justify-center shadow-lg">
            <Star className="w-6 h-6 text-white" />
          </div>
          <div>
            <p className="text-2xl font-bold text-cocorico-avocado dark:text-green-400">
              {stats.totalRecipes}
            </p>
            <p className="text-xs text-neutral-600 dark:text-neutral-400 font-semibold">
              Recetas creadas
            </p>
          </div>
        </div>
      </GlassCard>

      {/* Week Activity Widget */}
      <GlassCard className="p-4 hover:scale-[1.02] transition-transform">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 rounded-full bg-gradient-to-br from-cocorico-turquoise to-cocorico-avocado flex items-center justify-center shadow-lg">
            <TrendingUp className="w-6 h-6 text-white" />
          </div>
          <div>
            <p className="text-2xl font-bold text-cocorico-turquoise dark:text-teal-400">
              {stats.weekActivity}
            </p>
            <p className="text-xs text-neutral-600 dark:text-neutral-400 font-semibold">
              Actividad semanal
            </p>
          </div>
        </div>
      </GlassCard>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { createClientComponentClient } from "@/lib/supabase/client";
import { Trophy, TrendingUp } from "lucide-react";

interface Profile {
  xp: number;
  level: number;
}

export default function XpHud() {
  const supabase = createClientComponentClient();
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadProfile() {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        setLoading(false);
        return;
      }

      const { data } = await supabase
        .from("profiles")
        .select("xp, level")
        .eq("id", user.id)
        .single();

      if (data) {
        setProfile({ xp: data.xp || 0, level: data.level || 1 });
      }
      setLoading(false);
    }

    loadProfile();
  }, [supabase]);

  if (loading || !profile) return null;

  const xpForNextLevel = profile.level * 100;
  const xpProgress = profile.xp % 100;
  const progressPercentage = (xpProgress / 100) * 100;
  const pctToClass = (pct: number) => {
    const v = Math.max(0, Math.min(100, Math.round(pct / 5) * 5));
    return `w-pct-${v}` as const;
  };

  return (
    <div className="coco-glass-card p-4 rounded-2xl space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Trophy className="w-5 h-5 text-yellow-400" />
          <span className="font-bold text-lg glass-text-strong">
            Nivel {profile.level}
          </span>
        </div>
        <div className="flex items-center gap-1 text-sm text-muted-foreground">
          <TrendingUp className="w-4 h-4" />
          <span>{profile.xp} XP</span>
        </div>
      </div>

      <div className="space-y-1">
        <div className="flex justify-between text-xs text-muted-foreground">
          <span>{xpProgress} / 100 XP</span>
          <span>Siguiente nivel: {profile.level + 1}</span>
        </div>
        <div className="w-full bg-surface rounded-full h-2 overflow-hidden">
          <div
            className={[
              "h-full bg-gradient-to-r from-yellow-400 via-orange-400 to-red-400 rounded-full transition-all duration-500",
              pctToClass(progressPercentage),
            ].join(" ")}
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { RippleButton } from "@/components/ui/ripple-button";
import { createClientComponentClient } from "@/lib/supabase/client";

export function FeedbackForm() {
  const supabase = createClientComponentClient();
  const [loading, setLoading] = useState(false);
  const [file, setFile] = useState<File | null>(null);

  async function uploadImage() {
    if (!file) return null;

    const ext = file.name.split(".").pop();
    const filePath = `feedback/${Date.now()}.${ext}`;

    const { data, error } = await supabase.storage
      .from("assets")
      .upload(filePath, file);

    if (error) return null;

    return supabase.storage.from("assets").getPublicUrl(filePath).data.publicUrl;
  }

  async function submit(e: any) {
    e.preventDefault();
    setLoading(true);

    const form = new FormData(e.target);
    const category = form.get("category");
    const title = form.get("title");
    const message = form.get("message");
    const image_url = await uploadImage();

    await fetch("/api/feedback/new", {
      method: "POST",
      body: JSON.stringify({
        category,
        title,
        message,
        image_url
      })
    });

    setLoading(false);
    e.target.reset();
    setFile(null);
  }

  return (
    <form onSubmit={submit} className="space-y-4">
      <select
        name="category"
        aria-label="Categor├¡a de feedback"
        className="w-full rounded-xl bg-surface p-3"
        required
      >
        <option value="bug">Bug ­ƒÉ×</option>
        <option value="feature">Nueva funci├│n Ô£¿</option>
        <option value="improvement">Mejora ­ƒöº</option>
      </select>

      <input
        name="title"
        className="w-full rounded-xl bg-surface p-3"
        placeholder="T├¡tulo"
        required
      />

      <textarea
        name="message"
        className="w-full rounded-xl bg-surface p-3"
        placeholder="Describe tu sugerenciaÔÇª"
        required
      />

      <input
        type="file"
        aria-label="Adjuntar captura"
        onChange={(e) => setFile(e.target.files?.[0] ?? null)}
      />

      <RippleButton disabled={loading} className="bg-primary text-white">
        Enviar feedback
      </RippleButton>
    </form>
  );
}

"use client";

import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils";

type BackgroundVariant =
  | "home-free"
  | "home-premium"
  | "recipes-free"
  | "recipes-neutral"
  | "learn"
  | "stats"
  | "community"
  | "feedback"
  | "profile"
  | "onboarding"
  | "dashboard";

/**
 * Devuelve la clase CSS de fondo seg├║n la ruta actual y, opcionalmente,
 * seg├║n si el usuario es premium o no.
 */
function resolveBackgroundVariant(
  pathname: string,
  isPremium?: boolean
): BackgroundVariant {
  // Normalizamos para evitar problemas con locale
  // Ej: /es/dashboard, /en/dashboard etc.
  const path = pathname.replace(/^\/[a-z]{2}\//, "/");

  if (path === "/" || path.startsWith("/dashboard")) {
    return isPremium ? "home-premium" : "home-free";
  }

  if (path.startsWith("/recipes/search") || path.startsWith("/recipes")) {
    // Para listados largos mejor un fondo m├ís neutro
    return "recipes-neutral";
  }

  if (path.startsWith("/learn")) {
    return "learn";
  }

  if (path.startsWith("/dashboard/stats")) {
    return "stats";
  }

  if (path.startsWith("/community")) {
    return "community";
  }

  if (path.startsWith("/dashboard/feedback")) {
    return "feedback";
  }

  if (path.startsWith("/dashboard/profile") || path.startsWith("/settings")) {
    return "profile";
  }

  if (path.startsWith("/onboarding")) {
    return "onboarding";
  }

  // Fallback general
  return isPremium ? "home-premium" : "home-free";
}

type AppBackgroundProps = {
  children: React.ReactNode;
  /** Forzar un fondo concreto (opcional); si no, se deduce por ruta */
  variantOverride?: BackgroundVariant;
  /** Si ya tienes el plan disponible, p├ísalo para elegir mejor el fondo home */
  isPremium?: boolean;
  className?: string;
};

export function AppBackground({
  children,
  variantOverride,
  isPremium,
  className,
}: AppBackgroundProps) {
  const pathname = usePathname();
  const variant =
    variantOverride ?? resolveBackgroundVariant(pathname ?? "/", isPremium);

  const variantClass: Record<BackgroundVariant, string> = {
    "home-free": "coco-bg-home-free",
    "home-premium": "coco-bg-home-premium",
    "recipes-free": "coco-bg-recipes-free",
    "recipes-neutral": "coco-bg-recipes-neutral",
    learn: "coco-bg-learn",
    stats: "coco-bg-stats",
    community: "coco-bg-community",
    feedback: "coco-bg-feedback",
    profile: "coco-bg-profile",
    onboarding: "coco-bg-onboarding",
    dashboard: "coco-bg-home-free",
  };

  return (
    <div className={cn("app-root-bg-inner min-h-screen bg-transparent", className)}>
      {/* Background layer removed to allow Wallpaper component to be visible */}
      {children}
    </div>
  );
}

export default AppBackground;
export type { BackgroundVariant };

