/**
 * UnifiedNavbar - Componente de navegaci├│n consolidado
 * 
 * Combina las mejores caracter├¡sticas de:
 * - Navbar.tsx (manejo de auth de Supabase)
 * - SiteHeader.tsx (i18n con next-intl, componentes shadcn)
 * - LocaleNavbar.tsx (soporte de locale en rutas)
 * 
 * Caracter├¡sticas:
 * - Ô£à Internacionalizaci├│n completa con next-intl
 * - Ô£à Autenticaci├│n con Supabase
 * - Ô£à Responsive (desktop + mobile con Sheet)
 * - Ô£à Indicador visual de ruta activa
 * - Ô£à Men├║ desplegable de usuario
 * - Ô£à Theme toggle y language selector integrados
 * - Ô£à Dropdowns controlados por estado (click) para mejor UX
 */

interface NavLink {
  href: string;
  labelKey: string;
  icon: string;
}

const mainNavLinks: NavLink[] = [
  { href: "/", labelKey: "nav.home", icon: "­ƒÅá" },
  { href: "/recipes", labelKey: "nav.recipes", icon: "­ƒôû" },
  { href: "/dashboard/favorites", labelKey: "nav.favorites", icon: "Ô¡É" },
  { href: "/dashboard/stats", labelKey: "nav.stats", icon: "­ƒôè" },
  { href: "/chat", labelKey: "nav.chat", icon: "­ƒÆ¼" },
];

const scannerMenu = {
  label: "Scanner",
  items: [
    { href: "/scanner", label: "Escanear", icon: "­ƒôÀ" },
    { href: "/scanner/history", label: "Historial", icon: "­ƒôï" },
  ],
};

const communityMenu = {
  label: "Comunidad",
  items: [
    { href: "/community", label: "Inicio", icon: "­ƒÅá" },
    { href: "/community/feed", label: "Feed", icon: "­ƒô░" },
    { href: "/community/challenges", label: "Retos", icon: "­ƒÅå" },
    { href: "/community/chat", label: "Chat", icon: "­ƒÆ¼" },
  ],
};

const userMenuLinks: NavLink[] = [
  { href: "/dashboard", labelKey: "nav.dashboard", icon: "­ƒôè" },
  { href: "/voice-chat", labelKey: "nav.voiceChat", icon: "­ƒÄÖ´©Å" },
  { href: "/learn", labelKey: "nav.learn", icon: "­ƒÄô" },
  { href: "/dashboard/challenges", labelKey: "nav.challenges", icon: "­ƒÅå" },
  { href: "/dashboard/achievements", labelKey: "nav.achievements", icon: "­ƒÅà" },
  { href: "/dashboard/favorites", labelKey: "nav.favorites", icon: "Ô¡É" },
  { href: "/pricing", labelKey: "nav.pricing", icon: "­ƒÆÄ" },
  { href: "/dashboard/feedback", labelKey: "nav.feedback", icon: "­ƒôØ" },
  { href: "/settings", labelKey: "nav.settings", icon: "ÔÜÖ´©Å" },
  { href: "/community/feed", labelKey: "nav.feed", icon: "­ƒô░" },
  { href: "/community/challenges", labelKey: "nav.challenges", icon: "­ƒÅå" },
