        </div>

        {/* Empty State */}
        {recipes.length === 0 && !showDemo && (
          <GlassCard className={cn(
            "text-center mt-10 p-12",
          )} variant={plan === 'premium' ? 'premium' : 'accent'}>
            <p className={cn(
              "text-lg mb-6",
              plan === "premium" ? "glass-text-premium" : "text-neutral-600 dark:text-neutral-400"
