import { supabase } from "@/app/lib/supabase-client";

export async function savePushToken(token: string) {
  if (!token) return;
  
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) {
    console.log("ÔØî No hay usuario logueado para guardar token push");
    return;
  }

  // Intentar actualizar user_metadata (m├ís simple que crear tabla nueva)
  const { error } = await supabase.auth.updateUser({
    data: { push_token: token }
  });

  if (error) {
    console.error("Error guardando token push:", error);
  } else {
    console.log("Ô£à Token push guardado en user metadata");
  }
}

export async function getPushToken(userId: string) {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return null;
  
  return user.user_metadata?.push_token || null;
}

import { supabase } from "@/app/lib/supabase-client";

/**
 * Sube un archivo de avatar al bucket de Supabase Storage
 * @param file - El archivo de imagen a subir
 * @param userId - El ID del usuario (para organizar por carpetas)
 * @returns La URL p├║blica del avatar subido
 */
export async function uploadAvatar(file: File, userId: string): Promise<string> {
  // Sanitizar nombre del archivo
  const fileName = `${userId}/${Date.now()}-${file.name.replace(/\s+/g, "_")}`;
  
  // Subir al bucket 'avatars' (o 'recipes' si prefieres usar el mismo)
  const { data, error } = await supabase.storage
    .from("avatars")
    .upload(fileName, file, { 
      upsert: true,
      contentType: file.type
    });

  if (error) throw error;

  // Obtener la URL p├║blica
  const { data: publicUrlData } = supabase.storage
    .from("avatars")
    .getPublicUrl(fileName);

  return publicUrlData.publicUrl;
}

/**
 * Elimina un avatar del storage
 * @param avatarUrl - La URL completa del avatar a eliminar
 */
export async function deleteAvatar(avatarUrl: string): Promise<void> {
  // Extraer el path del avatar de la URL
  const path = avatarUrl.split('/avatars/')[1];
  if (!path) return;

  const { error } = await supabase.storage
    .from("avatars")
    .remove([path]);

  if (error) throw error;
}

import { ValidationResult } from "@/types/api";

export function validateMessage(message: unknown): ValidationResult<string> {
  if (!message || typeof message !== "string") {
    return {
      isValid: false,
      error: "El mensaje debe ser un texto no vac├¡o"
    };
  }

  const trimmed = message.trim();
  if (trimmed.length === 0) {
    return {
      isValid: false,
      error: "El mensaje no puede estar vac├¡o"
    };
  }

  if (trimmed.length > 1000) {
    return {
      isValid: false,
      error: "El mensaje no puede exceder 1000 caracteres"
    };
  }

  return {
    isValid: true,
    value: trimmed
  };
}

export function validateReturnTo(url: string): ValidationResult<string> {
  try {
    // Only allow relative paths
    if (url.startsWith('http')) {
      const urlObj = new URL(url);
      // Only allow URLs from same origin
      if (urlObj.origin !== window.location.origin) {
        return {
          isValid: false,
          error: "URL de retorno no v├ílida"
        };
      }
      // Extract pathname+search+hash
      url = urlObj.pathname + urlObj.search + urlObj.hash;
    }

    // Basic safety checks
    if (!url.startsWith('/')) {
      return {
        isValid: false,
        error: "La ruta debe comenzar con /"
      };
    }

    return {
      isValid: true,
      value: url
    };
  } catch (e) {
    return {
      isValid: false,
      error: "URL de retorno inv├ílida"
    };
  }
}

